window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d0dfcf097ef0b2a6"]={"versions": [{"id": "FIG-d0dfcf097ef0b2a6", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von mehrsprachigen und einsprachigen Langnamen im Rahmen des AUTOSAR Generic Structure Template (Pakete <code>MultilanguageData</code>, <code>LanguageDataModel</code>, <code>SingleLanguageData</code> und <code>InlineTextModel</code>). Es definiert die strukturelle Ableitung sprachspezifischer Langnamen aus einem gemeinsamen Textmodell.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>MultilanguageData::MultilanguageLongName</code>: Aggregiert über eine Komposition mit Rollenname <code>+l4</code> und Multiplizität <code>1..*</code> sprachspezifische Langnamenelemente vom Typ <code>LanguageDataModel::LLongName</code>.\n</li><li><code>LanguageDataModel::LLongName</code>: Stereotyp <code>«atpMixedString»</code>, realisiert das abstrakte Merkmal <code>LanguageSpecific</code> und generalisiert das Basiselement <code>InlineTextModel::MixedContentForLongName</code>.\n</li><li><code>SingleLanguageData::SingleLanguageLongName</code>: Stereotyp <code>«atpMixedString»</code>, generalisiert direkt <code>InlineTextModel::MixedContentForLongName</code>.\n</li><li><code>InlineTextModel::MixedContentForLongName</code>: Stereotyp <code>«atpMixedString»</code>, dient als abstrakte/gemeinsame Basisklasse für gemischte Textinhalte in Langnamen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Die Instanziierung erfordert bei mehrsprachigen Elementen (<code>MultilanguageLongName</code>) mindestens einen sprachspezifischen Eintrag (<code>LLongName</code> via <code>+l4</code>), wohingegen ein einsprachiger Langname direkt als <code>SingleLanguageLongName</code> ausgeprägt wird. Beide Varianten greifen strukturell auf denselben Inline-Textinhalt zurück.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Definition für Dokumentationselemente. Modellierer und Codegeneratoren müssen sicherstellen, dass in multilingualen Kontexten mindestens eine Sprachvariante (<code>1..*</code>) vorhanden ist und die Sprachauszeichnung der Vorgabe entspricht. Die Kennzeichnung mit <code>«atpMixedString»</code> signalisiert ein mixed-content XML-Schemafragment (Mischung aus freiem Fließtext und Markup-Tags).</p>"}, {"id": "FIG-1bdecfcfc48e892c", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von mehrsprachigen und einsprachigen Langnamen im Rahmen des AUTOSAR Generic Structure Template (Pakete <code>MultilanguageData</code>, <code>LanguageDataModel</code>, <code>SingleLanguageData</code> und <code>InlineTextModel</code>). Es definiert die strukturelle Ableitung sprachspezifischer Langnamen aus einem gemeinsamen Textmodell.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>MultilanguageData::MultilanguageLongName</code>: Aggregiert über eine Komposition mit Rollenname <code>+l4</code> und Multiplizität <code>1..*</code> sprachspezifische Langnamenelemente vom Typ <code>LanguageDataModel::LLongName</code>.\n</li><li><code>LanguageDataModel::LLongName</code>: Stereotyp <code>«atpMixedString»</code>, realisiert das abstrakte Merkmal <code>LanguageSpecific</code> und generalisiert das Basiselement <code>InlineTextModel::MixedContentForLongName</code>.\n</li><li><code>SingleLanguageData::SingleLanguageLongName</code>: Stereotyp <code>«atpMixedString»</code>, generalisiert direkt <code>InlineTextModel::MixedContentForLongName</code>.\n</li><li><code>InlineTextModel::MixedContentForLongName</code>: Stereotyp <code>«atpMixedString»</code>, dient als abstrakte/gemeinsame Basisklasse für gemischte Textinhalte in Langnamen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Die Instanziierung erfordert bei mehrsprachigen Elementen (<code>MultilanguageLongName</code>) mindestens einen sprachspezifischen Eintrag (<code>LLongName</code> via <code>+l4</code>), wohingegen ein einsprachiger Langname direkt als <code>SingleLanguageLongName</code> ausgeprägt wird. Beide Varianten greifen strukturell auf denselben Inline-Textinhalt zurück.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Definition für Dokumentationselemente. Modellierer und Codegeneratoren müssen sicherstellen, dass in multilingualen Kontexten mindestens eine Sprachvariante (<code>1..*</code>) vorhanden ist und die Sprachauszeichnung der Vorgabe entspricht. Die Kennzeichnung mit <code>«atpMixedString»</code> signalisiert ein mixed-content XML-Schemafragment (Mischung aus freiem Fließtext und Markup-Tags).</p>"}, {"id": "FIG-c3cfdcdce385f440", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition der Metamodellstruktur von <code>MultilanguageLongName</code>, <code>SingleLanguageLongName</code> und der feingranularen Zusammensetzung von <code>MixedContentForLongName</code> aus typografischen Inline-Elementen innerhalb des AUTOSAR Generic Structure Template.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>MultilanguageLongName</code>: Komponiert über <code>+l4</code> mit Kardinalität <code>1..*</code> Instanzen von <code>LLongName</code>.\n</li><li><code>LanguageSpecific</code>: Abstrakte Klasse mit Attribut <code>+ l :LEnum</code> zur Festlegung des Sprachcodes.\n</li><li><code>LLongName</code>: Stereotyp <code>«atpMixedString»</code>, erbt von <code>LanguageSpecific</code> und generalisiert <code>MixedContentForLongName</code>.\n</li><li><code>SingleLanguageLongName</code>: Stereotyp <code>«atpMixedString»</code>, generalisiert direkt <code>MixedContentForLongName</code>.\n</li><li><code>MixedContentForLongName</code>: Stereotyp <code>«atpMixedString»</code>, fungiert als Container und komponiert:\n<ul class=\"fig-list\"><li><code>EmphasisText</code> (Stereotyp <code>«atpMixedString»</code>) über Rolle <code>+e</code> (Kardinalität <code>1</code>), mit Attributen <code>+ color :String [0..1]</code>, <code>+ font :EEnumFont [0..1]</code>, <code>+ type :EEnum [0..1]</code>.\n</li><li><code>Superscript</code> (Stereotyp <code>«primitive»</code>) über Rollen <code>+sub</code> (Kardinalität <code>1</code>) und <code>+sup</code> (Kardinalität <code>1</code>).\n</li><li><code>IndexEntry</code> (Stereotyp <code>«atpMixedString»</code>) über Rolle <code>+ie</code> (Kardinalität <code>1</code>).\n</li><li><code>Tt</code> über Rolle <code>+tt</code> (Kardinalität <code>1</code>), mit Attributen <code>+ term :String</code> und <code>+ type :NameToken</code>.\n</li></ul>\n</li><li><code>EmphasisText</code>, <code>Superscript</code> und <code>IndexEntry</code> besitzen wechselseitige Verschachtelungen über Kompositionen mit Multiplizitäten <code>1</code>.\n</li><li><code>Tt</code> referenziert bzw. aggregiert <code>EmphasisText</code> über Rolle <code>+tt</code> mit Kardinalität <code>0..1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell. Beim Parsen oder Erzeugen eines Langnamens kann der Textinhalt (<code>MixedContentForLongName</code>) aus freiem Text sowie beliebig geschachtelten typografischen Fragmenten (Hervorhebungen, Hoch-/Tiefstellung, Indexeinträge, Teletype/Monospace-Begriffe) bestehen. Die Sprachzuordnung erfolgt bei multilingualen Langnamen über das Attribut <code>l</code> der jeweiligen <code>LLongName</code>-Instanz.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert das normative XML-Schema für Langnamen. Die Attribute <code>color</code>, <code>font</code> und <code>type</code> bei <code>EmphasisText</code> sind optional (<code>[0..1]</code>). <code>Superscript</code> dient gleichzeitig der Repräsentation von Hoch- (<code>sup</code>) und Tiefstellungen (<code>sub</code>). Die gemischte Textstruktur (<code>«atpMixedString»</code>) erfordert in Tools und Generatoren die Unterstützung strukturierter Inline-Tags innerhalb des Textflusses.</p>"}, {"id": "FIG-239abd720909cd25", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition der Metamodellstruktur von <code>MultilanguageLongName</code>, <code>SingleLanguageLongName</code> und der feingranularen Zusammensetzung von <code>MixedContentForLongName</code> aus typografischen Inline-Elementen innerhalb des AUTOSAR Generic Structure Template.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>MultilanguageLongName</code>: Komponiert über <code>+l4</code> mit Kardinalität <code>1..*</code> Instanzen von <code>LLongName</code>.\n</li><li><code>LanguageSpecific</code>: Abstrakte Klasse mit Attribut <code>+ l :LEnum</code>.\n</li><li><code>LLongName</code>: Stereotyp <code>«atpMixedString»</code>, erbt von <code>LanguageSpecific</code> und generalisiert <code>MixedContentForLongName</code>.\n</li><li><code>SingleLanguageLongName</code>: Stereotyp <code>«atpMixedString»</code>, generalisiert <code>MixedContentForLongName</code>.\n</li><li><code>MixedContentForLongName</code>: Stereotyp <code>«atpMixedString»</code>, aggregiert per Komposition:\n<ul class=\"fig-list\"><li><code>EmphasisText</code> (Stereotyp <code>«atpMixedString»</code>) über Rolle <code>+e</code> (Multiplizität <code>1</code>), mit Attributen <code>+ color :String [0..1]</code>, <code>+ font :EEnumFont [0..1]</code>, <code>+ type :EEnum [0..1]</code>.\n</li><li><code>Superscript</code> (Stereotyp <code>«primitive»</code>) über Rollen <code>+sub</code> (Multiplizität <code>1</code>) und <code>+sup</code> (Multiplizität <code>1</code>).\n</li><li><code>IndexEntry</code> (Stereotyp <code>«atpMixedString»</code>) über Rolle <code>+ie</code> (Multiplizität <code>1</code>).\n</li><li><code>Tt</code> über Rolle <code>+tt</code> (Multiplizität <code>1</code>), mit Attributen <code>+ term :String</code>, <code>+ texRender :String [0..1]</code> und <code>+ type :NameToken</code>.\n</li></ul>\n</li><li><code>EmphasisText</code> und <code>IndexEntry</code> stehen über <code>+sup 1</code> mit <code>Superscript</code> in Beziehung; <code>EmphasisText</code> bindet zudem an <code>Tt</code> über <code>+tt</code> (<code>0..1</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell. Beim Parsen oder Erzeugen eines Langnamens kann der Textinhalt (<code>MixedContentForLongName</code>) aus freiem Text sowie beliebig geschachtelten typografischen Fragmenten (Hervorhebungen, Hoch-/Tiefstellung, Indexeinträge, Teletype/Monospace-Begriffe) bestehen. Die Sprachzuordnung erfolgt bei multilingualen Langnamen über das Attribut <code>l</code> der jeweiligen <code>LLongName</code>-Instanz.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative XML- und Modellanforderung für Dokumentationselemente. Das hinzugefügte optionale Attribut <code>texRender :String [0..1]</code> an <code>Tt</code> ermöglicht die Hinterlegung einer spezifischen TeX-Darstellung für Monospace-Termini in Generierungsketten. Tooling muss diese Eigenschaft bei der PDF- und Dokumentgenerierung berücksichtigen.</p>"}, {"id": "FIG-044f080e25f2df1d", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition der Metamodellstruktur von <code>MultilanguageLongName</code>, <code>SingleLanguageLongName</code> und der feingranularen Zusammensetzung von <code>MixedContentForLongName</code> aus typografischen Inline-Elementen innerhalb des AUTOSAR Generic Structure Template.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>MultilanguageLongName</code>: Komponiert über <code>+l4</code> mit Kardinalität <code>1..*</code> Instanzen von <code>LLongName</code>.\n</li><li><code>LanguageSpecific</code>: Abstrakte Klasse mit Attribut <code>+ l: LEnum</code>.\n</li><li><code>LLongName</code>: Stereotyp <code>«atpMixedString»</code>, weist das Attribut <code>+ blueprintValue: String [0..1]</code> auf, erbt von <code>LanguageSpecific</code> und generalisiert <code>MixedContentForLongName</code>.\n</li><li><code>SingleLanguageLongName</code>: Stereotyp <code>«atpMixedString»</code>, generalisiert <code>MixedContentForLongName</code>.\n</li><li><code>MixedContentForLongName</code>: Stereotyp <code>«atpMixedString»</code>, komponiert:\n<ul class=\"fig-list\"><li><code>EmphasisText</code> (Stereotyp <code>«atpMixedString»</code>) über <code>+e</code> (Kardinalität <code>1</code>), mit Attributen <code>+ color: String [0..1]</code>, <code>+ font: EEnumFont [0..1]</code>, <code>+ type: EEnum [0..1]</code>.\n</li><li><code>Superscript</code> (Stereotyp <code>«primitive»</code>) über getrennte Assoziationen <code>+sub</code> (<code>1</code>) und <code>+sup</code> (<code>1</code>).\n</li><li><code>IndexEntry</code> (Stereotyp <code>«atpMixedString»</code>) über <code>+ie</code> (<code>1</code>).\n</li><li><code>Tt</code> über <code>+tt</code> (<code>1</code>), mit Attributen <code>+ term: String</code>, <code>+ texRender: String [0..1]</code>, <code>+ type: NameToken</code>.\n</li></ul>\n</li><li><code>EmphasisText</code> und <code>IndexEntry</code> sind jeweils über eigenständige Pfade für <code>+sup 1</code> und <code>+sub 1</code> mit <code>Superscript</code> verbunden.\n</li><li><code>Tt</code> bindet <code>EmphasisText</code> über <code>+tt</code> (<code>0..1</code>) ein.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell. Beim Parsen oder Erzeugen eines Langnamens kann der Textinhalt (<code>MixedContentForLongName</code>) aus freiem Text sowie beliebig geschachtelten typografischen Fragmenten (Hervorhebungen, Hoch-/Tiefstellung, Indexeinträge, Teletype/Monospace-Begriffe) bestehen. Die Sprachzuordnung erfolgt bei multilingualen Langnamen über das Attribut <code>l</code> der jeweiligen <code>LLongName</code>-Instanz.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung für AUTOSAR-Blueprint-Workflows und Dokumentationsinhalte. Mit <code>blueprintValue</code> kann für sprachspezifische Langnamen im Entwurfs-/Schablonenstadium ein abweichender Platzhalterwert hinterlegt werden. Bei der Instanziierung konkreter Modelle aus Blueprints ist dieses Feld entsprechend aufzulösen bzw. zu überschreiben.</p>"}, {"id": "FIG-3306640650955ca5", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition der Metamodellstruktur von <code>MultilanguageLongName</code>, <code>SingleLanguageLongName</code> und der feingranularen Zusammensetzung von <code>MixedContentForLongName</code> aus typografischen Inline-Elementen innerhalb des AUTOSAR Generic Structure Template.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>MultilanguageLongName</code>: Komponiert über <code>+l4</code> mit Kardinalität <code>1..*</code> Instanzen von <code>LLongName</code>.\n</li><li><code>LanguageSpecific</code>: Abstrakte Klasse mit Attribut <code>+ l: LEnum</code>.\n</li><li><code>LLongName</code>: Stereotyp <code>«atpMixedString»</code>, weist das Attribut <code>+ blueprintValue: String [0..1]</code> auf, erbt von <code>LanguageSpecific</code> und generalisiert <code>MixedContentForLongName</code>.\n</li><li><code>SingleLanguageLongName</code>: Stereotyp <code>«atpMixedString»</code>, generalisiert <code>MixedContentForLongName</code>.\n</li><li><code>MixedContentForLongName</code>: Stereotyp <code>«atpMixedString»</code>, komponiert:\n<ul class=\"fig-list\"><li><code>EmphasisText</code> (Stereotyp <code>«atpMixedString»</code>) über <code>+e</code> (Kardinalität <code>1</code>), mit Attributen <code>+ color: String [0..1]</code>, <code>+ font: EEnumFont [0..1]</code>, <code>+ type: EEnum [0..1]</code>.\n</li><li><code>Superscript</code> (Stereotyp <code>«primitive»</code>) über getrennte Assoziationen <code>+sub</code> (<code>1</code>) und <code>+sup</code> (<code>1</code>).\n</li><li><code>IndexEntry</code> (Stereotyp <code>«atpMixedString»</code>) über <code>+ie</code> (<code>1</code>).\n</li><li><code>Tt</code> über <code>+tt</code> (<code>1</code>), mit Attributen <code>+ term: String</code>, <code>+ texRender: String [0..1]</code>, <code>+ type: NameToken</code>.\n</li></ul>\n</li><li><code>EmphasisText</code> und <code>IndexEntry</code> sind jeweils über eigenständige Pfade für <code>+sup 1</code> und <code>+sub 1</code> mit <code>Superscript</code> verbunden.\n</li><li><code>Tt</code> bindet <code>EmphasisText</code> über <code>+tt</code> (<code>0..1</code>) ein.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell. Beim Parsen oder Erzeugen eines Langnamens kann der Textinhalt (<code>MixedContentForLongName</code>) aus freiem Text sowie beliebig geschachtelten typografischen Fragmenten (Hervorhebungen, Hoch-/Tiefstellung, Indexeinträge, Teletype/Monospace-Begriffe) bestehen. Die Sprachzuordnung erfolgt bei multilingualen Langnamen über das Attribut <code>l</code> der jeweiligen <code>LLongName</code>-Instanz.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung für AUTOSAR-Blueprint-Workflows und Dokumentationsinhalte. Mit <code>blueprintValue</code> kann für sprachspezifische Langnamen im Entwurfs-/Schablonenstadium ein abweichender Platzhalterwert hinterlegt werden. Bei der Instanziierung konkreter Modelle aus Blueprints ist dieses Feld entsprechend aufzulösen bzw. zu überschreiben.</p>"}], "trans": [{"from": "FIG-d0dfcf097ef0b2a6", "to": "FIG-1bdecfcfc48e892c", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-1bdecfcfc48e892c", "to": "FIG-c3cfdcdce385f440", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Die Paketpräfixe (<code>MultilanguageData::</code>, <code>InlineTextModel::</code>, <code>LanguageDataModel::</code>, <code>SingleLanguageData::</code>) entfallen in den Klassenbezeichnungen.\n</li><li>Das abstrakte Ziel <code>LanguageSpecific</code> wird als separate Klasse mit Attribut <code>+ l :LEnum</code> visualisiert, von der <code>LLongName</code> erbt.\n</li><li><code>SingleLanguageLongName</code> erbt nun direkt von <code>MixedContentForLongName</code>.\n</li><li><code>MixedContentForLongName</code> wird detailliert mit seinen Inline-Textelementen über Kompositionsbeziehungen dargestellt:\n<ul class=\"fig-list\"><li><code>EmphasisText</code> (Stereotyp <code>«atpMixedString»</code>) mit Attributen <code>+ color :String [0..1]</code>, <code>+ font :EEnumFont [0..1]</code>, <code>+ type :EEnum [0..1]</code>, Rolle <code>+e</code> (Kardinalität <code>1</code>).\n</li><li><code>Superscript</code> (Stereotyp <code>«primitive»</code>) mit Rollen <code>+sub</code> (Kardinalität <code>1</code>) und <code>+sup</code> (Kardinalität <code>1</code>).\n</li><li><code>IndexEntry</code> (Stereotyp <code>«atpMixedString»</code>) mit Rolle <code>+ie</code> (Kardinalität <code>1</code>).\n</li><li><code>Tt</code> mit Attributen <code>+ term :String</code>, <code>+ type :NameToken</code>, Rolle <code>+tt</code> (Kardinalität <code>1</code>).\n</li></ul>\n</li><li>Zwischen <code>EmphasisText</code>, <code>Superscript</code> und <code>IndexEntry</code> bestehen gegenseitige Kompositionen mit Rollen <code>+sub 1</code> bzw. <code>+sup 1</code>.\n</li><li>Zwischen <code>Tt</code> und <code>EmphasisText</code> besteht eine Komposition mit Rolle <code>+tt</code> (Kardinalität <code>0..1</code>).\n</li></ul>"}, {"from": "FIG-c3cfdcdce385f440", "to": "FIG-239abd720909cd25", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Klasse <code>Tt</code>: Attribut <code>+ texRender :String [0..1]</code> hinzugefügt.\n</li><li>Die Kompositionsrollen zwischen <code>Superscript</code> und <code>EmphasisText</code> bzw. <code>IndexEntry</code> wurden von <code>+sub 1</code> zu <code>+sup 1</code> korrigiert.\n</li></ul>"}, {"from": "FIG-239abd720909cd25", "to": "FIG-044f080e25f2df1d", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Klasse <code>LLongName</code>: Attribut <code>+ blueprintValue: String [0..1]</code> hinzugefügt.\n</li><li>Assoziationen zwischen <code>Superscript</code> und <code>EmphasisText</code> bzw. <code>IndexEntry</code> aufgetrennt in separate Kanten für <code>+sup</code> (Kardinalität <code>1</code>) und <code>+sub</code> (Kardinalität <code>1</code>).\n</li></ul>"}, {"from": "FIG-044f080e25f2df1d", "to": "FIG-3306640650955ca5", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
